// Package auth 追加 SASLprep 身份准备（F-P7——rfc5034 §4 L287-289「The authorization
// identity generated by the SASL exchange is a simple username, and SHOULD use
// the SASLprep profile (RFC4013) of the StringPrep algorithm」；方案 A 裁决
// 2026-09-30 18:54：golang.org/x/text 承载 NFKC——映射/禁止/双向检查按 RFC4013 §2 逐条）。
// 消费点：POP3 AUTH PLAIN 认证身份准备（protocol/pop3 cmdAuth）。
// SRS 条目：FR-007（3.3.2）/NFR-004；TC-006；CON-002（x/text 纯 Go）。
// 修改历史：
//
//	2026-09-30 19:20:00 | 新建 | RFCSHOULD修正批次 RF-C（G2 批准 2026-09-30 18:28:20）
package auth

import (
	"errors"
	"unicode"

	"golang.org/x/text/unicode/norm"
)

// ErrSaslprepProhibited SASLprep 禁止字符命中（RFC4013 §2.3——返回错误由调用方按认证失败处理）。
var ErrSaslprepProhibited = errors.New("saslprep: prohibited character in identity")

// ErrSaslprepBidi SASLprep 双向检查失败（RFC4013 §2.4——RandALCat 与非 RandALCat 混合）。
var ErrSaslprepBidi = errors.New("saslprep: invalid bidirectional string")

// SASLprep 按 RFC4013 准备 SASL 身份串（authorization identity）。
// 步骤（RFC4013 §2 逐条）：映射（非 ASCII 空白→SP）→NFKC 规范化→禁止字符检查
// （控制符/代理区/私有区/非字符码位/不适合显示）→双向检查。
// 参数：identity 认证交换产生的身份串。返回：准备后串；禁止/双向命中返回对应错误。
func SASLprep(identity string) (string, error) {
	// 1. 映射（RFC3454 B.1/Common）：非 ASCII 空白字符 → U+0020
	mapped := mapNonASCIISpace(identity)
	// 2. 规范化：NFKC（x/text 承载）
	nfkc := norm.NFKC.String(mapped)
	// 3. 禁止字符（RFC3454 C.2.1/C.2.2/C.3/C.4/C.5/C.6/C.7/C.8 常用集——控制符/
	//    代理/私用区/非字符/不适合显示；C.1.2 已在映射步处理，C.1.1 ASCII 空白合法）
	for _, r := range nfkc {
		if isProhibited(r) {
			return "", ErrSaslprepProhibited
		}
	}
	// 4. 双向检查（RFC4013 §2.4）：含 RandALCat 时须全串 RandALCat 或首尾 RandALCat 且中段仅 RandALCat/NSM 简化口径
	if err := checkBidi(nfkc); err != nil {
		return "", err
	}
	return nfkc, nil
}

// mapNonASCIISpace 非 ASCII 空白映射（RFC3454 B.1 表：U+00A0/U+1680/U+2000-U+200B/
// U+2028/U+2029/U+202F/U+205F/U+3000 → SP；U+0000-U+001F+C.1.1 ASCII 空白不在映射面）。
func mapNonASCIISpace(s string) string {
	var b []rune
	for _, r := range s {
		switch r {
		case 0x00A0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000:
			b = append(b, ' ')
		default:
			if r >= 0x2000 && r <= 0x200B {
				b = append(b, ' ')
			} else {
				b = append(b, r)
			}
		}
	}
	return string(b)
}

// isProhibited 禁止字符判定（RFC3454 常用禁止集）。
func isProhibited(r rune) bool {
	switch {
	// C.2.1 ASCII 控制字符（U+0000-U+001F/U+007F）
	case r <= 0x001F, r == 0x007F:
		return true
	// C.2.2 非 ASCII 控制字符（常用区段：U+0080-U+009F/U+2028/U+2029 已映射处理、行分隔段）
	case r >= 0x0080 && r <= 0x009F, r == 0x06DD, r == 0x070F, r == 0x180E,
		r == 0x200E, r == 0x200F, r == 0x2028, r == 0x2029,
		r >= 0x2060 && r <= 0x2063, r == 0xFEFF,
		r >= 0xFFF9 && r <= 0xFFFC,
		r >= 0x1D173 && r <= 0x1D17A,
		r >= 0xE0001 && r <= 0xE007F:
		return true
	// C.5 私用区 / C.4 非字符码位 / C.3 代理区（Go rune 无代理，防御性保留）
	case r >= 0xE000 && r <= 0xF8FF,
		r >= 0xF0000 && r <= 0xFFFFD,
		r >= 0x100000 && r <= 0x10FFFD:
		return true
	// C.4 非字符码位（各平面末两码位）
	case (r&0xFFFE) == 0xFFFE || (r&0xFFFE) == 0xFFFF:
		return r > 0x7F // BMP 内 ASCII 范围不命中（0xFFFE 判定已 >0x7F，防御性显式）
	// C.6 不适合显示的字符（常用区段）
	case r == 0xFFF9, r == 0xFFFA, r == 0xFFFB, r == 0xFFFC,
		r >= 0xFFFA && r <= 0xFFFD,
		r >= 0x2FFE && r <= 0x2FFF,
		r >= 0xE0000 && r <= 0xE0FFF:
		return true
	}
	return false
}

// checkBidi 双向检查（RFC4013 §2.4 简化忠实形态：含 RandALCat 字符时，
// 全串必须 RandALCat 或首尾 RandALCat 且中段 RandALCat/NSM）。
func checkBidi(s string) error {
	hasRandAL := false
	for _, r := range s {
		if isRandALCat(r) {
			hasRandAL = true
			break
		}
	}
	if !hasRandAL {
		return nil // 无 RandALCat 字符→无约束
	}
	runes := []rune(s)
	first := runes[0]
	last := runes[len(runes)-1]
	if !isRandALCat(first) || !isRandALCat(last) {
		return ErrSaslprepBidi // 规则 2：首尾须 RandALCat
	}
	for _, r := range runes[1 : len(runes)-1] {
		if !isRandALCat(r) && !unicode.Is(unicode.Mn, r) { // NSM≈组合记号（Mn 近似）
			return ErrSaslprepBidi // 规则 1：中段仅 RandALCat/NSM
		}
	}
	return nil
}

// isRandALCat RandALCat 判定（RFC3454 D.1 常用区段：阿拉伯/希伯来字母系）。
func isRandALCat(r rune) bool {
	return (r >= 0x05BE && r <= 0x05F4) || (r >= 0x061C && r <= 0x06D5) ||
		(r >= 0x0700 && r <= 0x070D) || r == 0x0710 || (r >= 0x0712 && r <= 0x072C) ||
		(r >= 0x0780 && r <= 0x07A5) || (r >= 0xFB1D && r <= 0xFB4F) ||
		(r >= 0x0600 && r <= 0x0605)
}
